WITH enriched AS (SELECT id, order_id, method, amount, paid_at, status, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) amount_share, AVG(amount) OVER (PARTITION BY order_id, status) order_id_avg_amount, DENSE_RANK() OVER (PARTITION BY method ORDER BY amount DESC NULLS FIRST) amount_dense_rank FROM payments) SELECT id, order_id, method, paid_at, status, order_id_avg_amount, amount_dense_rank, CASE WHEN status RLIKE '^(SUCCESS|REFUNDED)$' THEN 'GROUP_A' WHEN status RLIKE '^(FAILED)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS status_zone FROM enriched;
